insert into public.challenges(id,title,prompt,category,difficulty,duration_minutes,xp,channel) values
(3000,'Prática: Linhas e formas','Desenhe cinco objetos usando círculos, caixas e cilindros.','Fundamentos','iniciante',5,30,'academy'),
(3001,'Prática: Volumes que giram','Desenhe uma xícara em três inclinações diferentes.','Fundamentos','intermediário',10,45,'academy'),
(3002,'Prática: Construção e desenho livre','Desenhe uma chaleira de observação e depois de memória.','Fundamentos','avançado',15,65,'academy'),
(3003,'Prática: O mapa do rosto','Faça três rostos frontais com formatos diferentes.','Rostos','iniciante',5,30,'academy'),
(3004,'Prática: Rosto de perfil','Desenhe três perfis variando nariz e mandíbula.','Rostos','intermediário',10,45,'academy'),
(3005,'Prática: Rostos em três quartos','Desenhe o mesmo rosto de frente, perfil e três quartos.','Rostos','avançado',15,65,'academy'),
(3006,'Prática: Um olho é uma esfera','Desenhe cinco olhos simples olhando em direções diferentes.','Olhos','iniciante',5,30,'academy'),
(3007,'Prática: Olhos em ângulos','Faça cinco olhos vistos de cima, baixo e lado.','Olhos','intermediário',10,45,'academy'),
