(3009,'Prática: Cabelo em massas','Crie três penteados com apenas cinco grandes mechas cada.','Cabelos','iniciante',5,30,'academy'),
(3010,'Prática: Volume e brilho','Desenhe um cabelo ondulado usando três valores de cinza.','Cabelos','intermediário',10,45,'academy'),
(3011,'Prática: Cabelo em movimento','Desenhe um penteado cacheado parado e depois ao vento.','Cabelos','avançado',15,65,'academy'),
(3012,'Prática: Palma e dedos simples','Desenhe cinco mãos abertas usando caixas e cilindros.','Mãos','iniciante',5,30,'academy'),
(3013,'Prática: Mãos segurando objetos','Desenhe uma mão segurando uma caneca, um lápis e uma esfera.','Mãos','intermediário',10,45,'academy'),
(3014,'Prática: Mãos em escorço','Desenhe três mãos em escorço usando sua mão como referência.','Mãos','avançado',15,65,'academy'),
(3015,'Prática: Tronco como volumes','Faça cinco manequins simples em pé com corpos variados.','Anatomia','iniciante',5,30,'academy'),
(3016,'Prática: Torção do tronco','Desenhe três troncos com torções suaves a partir de referências.','Anatomia','intermediário',10,45,'academy'),
