(3018,'Prática: Linha de ação','Faça seis gestos de 30 segundos com poses diferentes.','Poses','iniciante',5,30,'academy'),
(3019,'Prática: Equilíbrio e peso','Desenhe uma pessoa apoiada em duas pernas e depois em uma.','Poses','intermediário',10,45,'academy'),
(3020,'Prática: Ação com profundidade','Desenhe um personagem saltando em direção ao observador.','Poses','avançado',15,65,'academy'),
(3021,'Prática: Caixas no espaço','Desenhe cinco caixas usando um ponto de fuga.','Perspectiva','iniciante',5,30,'academy'),
(3022,'Prática: Dois pontos de fuga','Desenhe uma mesa e duas caixas em perspectiva de dois pontos.','Perspectiva','intermediário',10,45,'academy'),
(3023,'Prática: Perspectiva com observação','Desenhe um canto de quarto com móveis em orientações diferentes.','Perspectiva','avançado',15,65,'academy'),
(3024,'Prática: Três valores bastam','Desenhe esfera, cubo e cilindro com três valores de cinza.','Luz e sombra','iniciante',5,30,'academy'),
(3025,'Prática: Sombras que descrevem forma','Ilumine uma esfera e um cubo com a mesma fonte de luz.','Luz e sombra','intermediário',10,45,'academy'),
(3026,'Prática: Hierarquia da iluminação','Faça duas miniaturas da mesma cena com focos de luz diferentes.','Luz e sombra','avançado',15,65,'academy'),
(3027,'Prática: Uma paleta de três cores','Pinte um objeto com três cores e repita trocando a dominante.','Cores','iniciante',5,30,'academy'),
(3028,'Prática: Temperatura e ambiente','Faça versões quente e fria de uma pequena paisagem.','Cores','intermediário',10,45,'academy'),
(3029,'Prática: Cor com intenção','Crie duas paletas para uma cena: acolhimento e mistério.','Cores','avançado',15,65,'academy'),
(3030,'Prática: Tecido sobre o corpo','Desenhe uma camiseta sobre três troncos simples.','Roupas','iniciante',5,30,'academy'),
(3031,'Prática: Dobras e tensão','Compare uma manga dobrada e uma manga esticada.','Roupas','intermediário',10,45,'academy'),
(3032,'Prática: Materiais e silhueta','Crie a mesma capa em seda, lã e couro usando referência.','Roupas','avançado',15,65,'academy'),
(3033,'Prática: Animais em formas simples','Desenhe gato, coelho e coruja com círculos e ovais.','Animais','iniciante',5,30,'academy'),
(3034,'Prática: Estrutura animal','Desenhe um gato sentado e andando a partir de referências.','Animais','intermediário',10,45,'academy'),
(3035,'Prática: Criaturas convincentes','Crie um familiar misturando coruja e raposa, em duas poses.','Animais','avançado',15,65,'academy'),
(3036,'Prática: Planos de uma paisagem','Faça três paisagens pequenas usando apenas três planos.','Cenários','iniciante',5,30,'academy'),
(3037,'Prática: Escala e profundidade','Desenhe um caminho entre árvores mostrando profundidade.','Cenários','intermediário',10,45,'academy'),
(3038,'Prática: Cenário que conta história','Ilustre um ateliê abandonado com três pistas sobre seu dono.','Cenários','avançado',15,65,'academy'),
(3039,'Prática: Camadas com propósito','Desenhe uma caneca em três camadas nomeadas.','Desenho digital','iniciante',5,30,'academy'),
(3040,'Prática: Pincel e bordas','Pinte uma esfera e uma caixa com um único pincel.','Desenho digital','intermediário',10,45,'academy'),
(3041,'Prática: Fluxo de estudo digital','Crie uma pequena cena passando por miniatura, valores e cor.','Desenho digital','avançado',15,65,'academy'),
(3042,'Prática: 3 erros ao desenhar olhos','Compare dois olhos: um plano e outro construído sobre uma esfera.','Olhos','iniciante',3,15,'academy'),
(3043,'Prática: Volume sem desenhar cada fio','Desenhe um penteado usando três massas e seis linhas internas.','Cabelos','iniciante',3,15,'academy'),
(3044,'Prática: Como conferir um rosto torto','Faça um rosto e confira suas proporções usando dois eixos.','Rostos','iniciante',3,15,'academy'),
(3045,'Prática: Mãos em caixas e cilindros','Desenhe três mãos abertas sem unhas nem detalhes de pele.','Mãos','iniciante',3,15,'academy'),
(3046,'Prática: Escolha cores sem se perder','Faça três miniaturas da mesma caneca mudando a cor dominante.','Cores','iniciante',3,15,'academy') on conflict do nothing;
