insert into public.lesson_steps(lesson_id,step,title,explanation,diagram_key) values
('fundamentos-iniciante',1,'Construir','Trace linhas pelo movimento do braço, sem apertar o lápis.','fundamentos'),
('fundamentos-iniciante',2,'Organizar','Construa uma xícara com uma elipse e um cilindro.','fundamentos'),
('fundamentos-iniciante',3,'Conferir','Compare altura e largura antes de reforçar o contorno.','fundamentos'),
('fundamentos-intermediario',1,'Construir','Marque o eixo de um cilindro inclinado.','fundamentos'),
('fundamentos-intermediario',2,'Organizar','Envolva o volume com elipses seguindo esse eixo.','fundamentos'),
('fundamentos-intermediario',3,'Conferir','Apague linhas escondidas e confira se as elipses combinam.','fundamentos'),
('fundamentos-avancado',1,'Construir','Observe a silhueta de um objeto sem nomear suas partes.','fundamentos'),
('fundamentos-avancado',2,'Organizar','Reconstrua a silhueta com volumes e compare os espaços vazios.','fundamentos'),
('fundamentos-avancado',3,'Conferir','Escolha quais linhas de construção manter para expressar peso.','fundamentos'),
('rostos-iniciante',1,'Construir','Comece com uma esfera e acrescente a mandíbula.','rostos'),
('rostos-iniciante',2,'Organizar','Marque o centro e a linha dos olhos; ajuste à pessoa observada.','rostos'),
('rostos-iniciante',3,'Conferir','Distribua nariz e boca, comparando os espaços entre eles.','rostos'),
('rostos-intermediario',1,'Construir','Marque uma esfera, a orelha e a inclinação da mandíbula.','rostos'),
