('rostos-intermediario',3,'Conferir','Confira o encaixe do pescoço sem colá-lo ao queixo.','rostos'),
('rostos-avancado',1,'Construir','Faça os eixos curvarem sobre a esfera do crânio.','rostos'),
('rostos-avancado',2,'Organizar','Comprima o lado distante e observe a sobreposição do nariz.','rostos'),
('rostos-avancado',3,'Conferir','Compare as larguras dos olhos e as curvas da mandíbula.','rostos'),
('olhos-iniciante',1,'Construir','Imagine uma esfera encaixada na cavidade do rosto.','olhos'),
