('olhos-avancado',2,'Organizar','Varie a tensão das pálpebras e o arco das sobrancelhas.','olhos'),
('olhos-avancado',3,'Conferir','Use poucos detalhes para que a expressão continue legível.','olhos'),
('cabelos-iniciante',1,'Construir','Reserve um espaço entre crânio e silhueta do cabelo.','cabelos'),
