('maos-avancado',3,'Conferir','Observe espaços negativos entre dedos e evite comprimentos iguais.','maos'),
('anatomia-iniciante',1,'Construir','Use um oval para a caixa torácica e uma caixa para a pelve.','anatomia'),
('anatomia-iniciante',2,'Organizar','Ligue os volumes com uma coluna curva, sem detalhar músculos.','anatomia'),
('anatomia-iniciante',3,'Conferir','Adicione membros como cilindros e confira as proporções.','anatomia'),
