('perspectiva-iniciante',1,'Construir','Marque a linha do horizonte e um ponto de fuga.','perspectiva'),
('perspectiva-iniciante',2,'Organizar','Ligue os cantos da face frontal a esse ponto.','perspectiva'),
('perspectiva-iniciante',3,'Conferir','Feche a caixa e diferencie as faces por valores.','perspectiva'),
