('perspectiva-avancado',1,'Construir','Identifique altura do olhar e famílias de linhas paralelas.','perspectiva'),
('perspectiva-avancado',2,'Organizar','Compare a diminuição dos objetos e suas sobreposições.','perspectiva'),
('perspectiva-avancado',3,'Conferir','Ajuste pequenas irregularidades para evitar um cenário rígido.','perspectiva'),
('luz-iniciante',1,'Construir','Escolha uma única direção para a luz.','luz'),
